const DEMO_IMAGE="data:image/jpeg;base64,";
const DEMO_PRODUCTS = [{
 id:"kubota-kh-012", title:"クボタ KH-012 ミニショベル", category:"ミニショベル",
 description:"日本で取り扱うクボタ KH-012。1tクラスのコンパクトなミニショベルです。写真・動画・主要仕様をご確認いただけます。",
 videoUrl:"https://youtu.be/JqDzWHW0vWM", priceMode:"show", price:"¥1,500,000", status:"published", images:[DEMO_IMAGE],
 specs:[{key:"メーカー",value:"クボタ"},{key:"型式",value:"KH-012"},{key:"クラス",value:"1tクラス"},{key:"機械種類",value:"ミニショベル"},{key:"燃料",value:"ディーゼル"}]
},{
 id:"mini-excavator-contact", title:"小型ミニショベル", category:"ミニショベル",
 description:"在庫・仕様・状態に応じて価格をご案内する商品です。詳しい価格はLINEへメールを送ってご確認ください。",
 videoUrl:"https://youtu.be/JqDzWHW0vWM", priceMode:"contact", price:"", status:"published", images:[DEMO_IMAGE],
 specs:[{key:"機械種類",value:"ミニショベル"},{key:"価格",value:"お問い合わせ"}]
},{
 id:"sold-mini-excavator-example", title:"売約済み｜小型ミニショベル（表示例）", category:"ミニショベル",
 description:"これは売約済み商品の表示例です。実際に売約済みになると、このように「売約済み」と表示され、価格とLINEへのメール送信ボタンは表示されません。",
 videoUrl:"https://youtu.be/JqDzWHW0vWM", priceMode:"show", price:"", status:"sold", images:[DEMO_IMAGE],
 specs:[{key:"機械種類",value:"ミニショベル"},{key:"販売状態",value:"売約済み"}]
}];
async function getJSON(url){
 try{const r=await fetch(url);if(!r.ok)throw new Error("Request failed");return await r.json();}
 catch(e){
  let products=DEMO_PRODUCTS;
  try{const saved=localStorage.getItem("jmm_demo_products_v1");if(saved)products=JSON.parse(saved)}catch{}
  if(url==="/api/products") return products.filter(p=>p.status==="published" || p.status==="sold");
  const m=url.match(/^\/api\/products\/(.+)$/);
  if(m){const id=decodeURIComponent(m[1]);const p=products.find(x=>x.id===id && (x.status==="published" || x.status==="sold"));if(p)return p;}
  throw e;
} }
function money(p){return p.priceMode==="show"&&p.price?p.price:"価格はお問い合わせください"}
function card(p){
 const img=(p.images&&p.images[0])||DEMO_IMAGE;
 const chips=(p.specs||[]).slice(0,3).map(s=>`<span class="chip">${escapeHtml(s.key)}: ${escapeHtml(s.value)}</span>`).join("");
 const sold=p.status==="sold";
 return `<a class="product-card ${sold?"sold-card":""}" href="/product.html?id=${encodeURIComponent(p.id)}"><div class="product-image-wrap"><img class="product-img" src="${img}" onerror="this.onerror=null;this.src=DEMO_IMAGE" alt="${escapeHtml(p.title)}">${sold?'<span class="sold-ribbon">売約済み</span>':''}</div><div class="product-body"><div class="product-meta">${escapeHtml(p.category||"機械")}</div><div class="product-title">${escapeHtml(p.title)}</div><div class="spec-chips">${chips}</div><strong>${escapeHtml(sold?"売約済み":money(p))}</strong></div></a>`;
}
function escapeHtml(s){return String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[c]));}
async function loadFeatured(){try{const ps=await getJSON("/api/products");document.querySelector("#featured").innerHTML=ps.filter(p=>p.status!=="sold").slice(0,3).map(card).join("")||"<p>機械はまだ登録されていません。</p>"}catch(e){document.querySelector("#featured").innerHTML="<p>機械情報を読み込めませんでした。</p>"}}
let allProducts=[];
function sortProducts(ps){return [...ps].sort((a,b)=>{const rank={published:0,draft:1,sold:2};return (rank[a.status]??9)-(rank[b.status]??9)})}
async function loadProductsPage(){try{allProducts=sortProducts(await getJSON("/api/products"));renderProducts(allProducts)}catch(e){document.querySelector("#products").innerHTML="<p>機械情報を読み込めませんでした。</p>"}}
function renderProducts(ps){
 const root=document.querySelector("#products");
 const active=sortProducts(ps.filter(p=>p.status==="published"));
 const sold=sortProducts(ps.filter(p=>p.status==="sold"));
 const activeHtml=active.length?`<section class="catalog-group"><div class="catalog-group-head"><div><div class="eyebrow">販売中</div><h2>販売中の機械</h2></div><span class="catalog-count">${active.length}台</span></div><div class="products-grid">${active.map(card).join("")}</div></section>`:`<section class="catalog-group"><div class="catalog-group-head"><div><div class="eyebrow">販売中</div><h2>販売中の機械</h2></div></div><div class="notice">現在、販売中の機械はありません。</div></section>`;
 const soldHtml=sold.length?`<section class="catalog-group sold-group"><div class="catalog-group-head"><div><div class="eyebrow">販売終了</div><h2>売約済みの機械</h2></div><span class="catalog-count">${sold.length}台</span></div><div class="products-grid">${sold.map(card).join("")}</div></section>`:"";
 root.innerHTML=activeHtml+soldHtml;
}
function filterProducts(){const q=document.querySelector("#search").value.toLowerCase();renderProducts(sortProducts(allProducts.filter(p=>JSON.stringify(p).toLowerCase().includes(q))))}
function ytId(url){try{const u=new URL(url); if(u.hostname==="youtu.be") return u.pathname.slice(1); if(u.hostname.includes("youtube.com")) return u.searchParams.get("v")||u.pathname.split("/").pop();}catch{} return ""}
function lineMailUrl(product){
 const lineId=String(product?.lineId||"@sample-machinery").trim();
 const message=`「${product?.title||"商品"}」についてメールを送ります。`;
 return `https://line.me/R/oaMessage/${encodeURIComponent(lineId)}/?${encodeURIComponent(message)}`;
}
async function loadProductDetail(){
 const id=new URLSearchParams(location.search).get("id"); const el=document.querySelector("#detail");
 if(!id){el.innerHTML='<div class="container section"><h2>機械が指定されていません</h2><a class="btn" href="/products.html">機械一覧に戻る</a></div>';return}
 try{
  const p=await getJSON("/api/products/"+encodeURIComponent(id)); document.title=p.title+" | 日本ミニ建設機械";
  const main=(p.images&&p.images[0])||DEMO_IMAGE;
  const thumbs=(p.images||[]).map((im,i)=>`<img class="${i===0?"active":""}" src="${im}" onerror="this.onerror=null;this.src=DEMO_IMAGE" onclick="document.querySelector('#mainImg').src='${im}';document.querySelectorAll('.thumbs img').forEach(x=>x.classList.remove('active'));this.classList.add('active')" alt="">`).join("");
  const rows=(p.specs||[]).map(s=>`<div class="spec-row"><b>${escapeHtml(s.key)}</b><span>${escapeHtml(s.value)}</span></div>`).join("");
  const video=ytId(p.videoUrl)?`<div class="video"><iframe src="https://www.youtube.com/embed/${ytId(p.videoUrl)}" title="機械動画" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen></iframe></div>`:"<div class='notice'>動画はまだ登録されていません。</div>";
  const sold=p.status==="sold";
  const contactBox=sold?`<div class="contact-box sold-contact"><h3>この機械は売約済みです</h3><p class="muted">現在、こちらの機械は販売を終了しています。</p></div>`:`<div class="contact-box"><h3>この機械についてお問い合わせ</h3><p class="muted">LINEへメールを送ってご連絡いただけます。</p><a class="btn line" href="${lineMailUrl(p)}" target="_blank" rel="noopener">LINEへメールを送る</a><div style="margin-top:15px"><img class="qr" src="/assets/line-qr.png" onerror="this.style.display='none'" alt="LINE QR code"></div></div>`;
  el.innerHTML=`<section class="detail"><div class="container"><a class="muted" href="/products.html">← すべての機械</a><div class="detail-grid" style="margin-top:22px"><div><img id="mainImg" class="gallery-main" src="${main}" onerror="this.onerror=null;this.src=DEMO_IMAGE" alt="${escapeHtml(p.title)}"><div class="thumbs">${thumbs}</div></div><div><div class="eyebrow">${escapeHtml(p.category||"機械")}</div><h1>${escapeHtml(p.title)}</h1><p class="lead">${escapeHtml(p.description)}</p><div class="price">${escapeHtml(sold?"売約済み":money(p))}</div>${contactBox}</div></div>
  <div style="margin-top:55px"><div class="eyebrow">仕様</div><h2>主要仕様</h2><div class="spec-table">${rows||"<div class='notice'>仕様 will be added by the administrator.</div>"}</div></div>
  <div style="margin-top:55px"><div class="eyebrow">動画</div><h2>機械動画</h2>${video}</div></div></section>`;
 }catch(e){el.innerHTML='<div class="container section"><h2>機械が見つかりません</h2><p class="muted">この掲載は非公開になっている可能性があります。</p><a class="btn" href="/products.html">機械一覧に戻る</a></div>'}
}